import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { loginUser, selectAuthLoading } from "../store/slices/authSlice";
import { ROUTES } from "../config";
import { Eye, EyeOff, ArrowLeft, Loader2 } from "lucide-react";
import toast from "react-hot-toast";

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const Login = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const authLoading = useSelector(selectAuthLoading);

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState({});

  const handleLogin = async (e) => {
    e.preventDefault();
    const errs = {};
    const normalizedEmail = email.trim().toLowerCase();

    if (!normalizedEmail) {
      errs.email = "Email is required.";
    } else if (!EMAIL_REGEX.test(normalizedEmail)) {
      errs.email = "Invalid email.";
    }

    if (!password) {
      errs.password = "Password is required.";
    }

    if (Object.keys(errs).length > 0) {
      setErrors(errs);
      return;
    }

    setErrors({});

    const dashboardMap = {
      admin: ROUTES.ADMIN_DASHBOARD,
      user: ROUTES.USER_DASHBOARD,
      consultant: ROUTES.CONSULTANT_DASHBOARD,
    };

    try {
      const result = await dispatch(
        loginUser({
          email: normalizedEmail,
          password,
        }),
      ).unwrap();

      toast.success(result.message || "Login successful! Redirecting...");
      navigate(dashboardMap[result.user?.role] || ROUTES.HOME, {
        replace: true,
      });
    } catch (error) {
      const message = typeof error === "string" ? error : "Login failed.";
      toast.error(message);
    }
  };

  return (
    <div className="  min-h-dvh flex">
      {/* Left Side: Brand Imagery */}
      <div className="hidden lg:block lg:w-1/2 relative overflow-hidden shrink-0">
        <img
          src="/login.jpg"
          alt="Classic car in golden wheat field"
          className="absolute inset-0 w-full h-full object-cover pointer-events-none"
        />
      </div>

      {/* Right Side: Authentication Form */}
      <div className="flex-1 bg-white flex items-center justify-center shadow-[-7px_0px_11.4px_0px_rgba(0,0,0,0.25)] overflow-y-auto p-4">
        <div className="w-full max-w-xl">
          {/* Back Button */}
          <Link
            to={ROUTES.HOME}
            className="inline-flex items-center gap-2 text-base text-gray-600 hover:text-[#E2AB0B] font-medium transition-colors mb-2 group"
          >
            <ArrowLeft
              size={16}
              className="transition-transform group-hover:-translate-x-0.5"
            />
            Back to Home
          </Link>

          {/* Header */}
          <div className="mb-8">
            <h1 className="text-3xl font-medium text-[#000000] mb-3">
              Login to Your Account
            </h1>
            <p className="text-[#373737] text-base leading-relaxed">
              Great to have you with us again at netwerkmediums. Sign in now and
              receive insights that truly make a difference.
            </p>
          </div>
          {/* Form */}
          <form onSubmit={handleLogin} className="space-y-5">
            {/* Email Field */}
            <div>
              <label className="block text-base font-medium text-gray-800 mb-2 tracking-wide">
                Email
              </label>
              <input
                type="email"
                placeholder="Enter your email here..."
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className={`w-full px-4 py-3 bg-[#FEF5E7] border-none rounded text-sm text-gray-700 placeholder-gray-400 focus:ring-2 focus:ring-[#E2AB0B] outline-none transition-all ${errors.email ? "ring-2 ring-red-400" : ""}`}
              />
            </div>

            {/* Password Field with Visibility Toggle */}
            <div>
              <label className="block text-base font-medium text-gray-800 mb-2 tracking-wide">
                Password
              </label>
              <div className="relative">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Enter your password here..."
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className={`w-full px-4 py-3 bg-[#FEF5E7] border-none rounded text-sm text-gray-700 placeholder-gray-400 focus:ring-2 focus:ring-[#E2AB0B] outline-none transition-all ${errors.password ? "ring-2 ring-red-400" : ""}`}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
              <div className="text-right mt-2">
                <button
                  type="button"
                  className="text-sm font-medium text-[#E2AB0B]  transition-colors"
                >
                  Forgot Password?
                </button>
              </div>
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={authLoading}
              className="w-full bg-[#E2AB0B] disabled:opacity-60 text-white py-3 rounded font-bold text-sm transition-all shadow-md active:scale-[0.98] inline-flex items-center justify-center gap-2"
            >
              {authLoading ? (
                <>
                  <Loader2 size={16} className="animate-spin" />
                  Processing...
                </>
              ) : (
                "Login"
              )}
            </button>
          </form>

          {/* Sign Up Link */}
          <p className="text-center text-base text-gray-600 mt-6">
            Don't have an account?{" "}
            <Link
              to="/register"
              className="text-[#E2AB0B] font-medium hover:text-[#DF900A] transition-colors"
            >
              Register
            </Link>
          </p>
        </div>
      </div>

    </div>
  );
};

export default Login;
